COMMENT ON TABLE organizacion IS 'Tabla que almacena los datos de las organizaciones.';
COMMENT ON TABLE organizacion.denominacionlegal IS 'campo que almacena la denominación legal.';
COMMENT ON TABLE organizacion.domiciliolegal IS 'campo que almacena la dirección legal.';
COMMENT ON TABLE organizacion.domicilioreal IS 'campo que almacena la dirección real.';
COMMENT ON TABLE organizacion.e_mail IS 'campo que almacena el mail';
COMMENT ON TABLE organizacion.fax IS 'campo que almacena el número de fax de la organización.';
COMMENT ON TABLE organizacion.horarios IS 'campo que almacena los horarios de atención o funcionamiento de la organización.';
COMMENT ON TABLE organizacion.telefonos IS 'campo que almacena los números de teléfono de la organización, utilizados para contacto y comunicación con clientes, proveedores u otras partes interesadas.';
COMMENT ON TABLE organizacion.id_tipoorganizacion IS 'identificador del tipo de organización';